// 三态渲染状态机：输入事件序列 -> 输出状态序列
function reduce(state, event) {
  switch (event.type) {
    case 'FETCH_START':
      return { status: 'loading', data: null, error: null };
    case 'FETCH_SUCCESS':
      if (!event.items || event.items.length === 0) return { status: 'empty', data: [], error: null };
      return { status: 'success', data: event.items, error: null };
    case 'FETCH_ERROR':
      return { status: 'error', data: null, error: event.message };
    case 'RETRY':
      return state.status === 'error' ? { status: 'loading', data: null, error: null } : state;
    default:
      return state;
  }
}
function trace(events) {
  let s = { status: 'idle', data: null, error: null };
  const out = [];
  for (const e of events) { s = reduce(s, e); out.push(s.status); }
  return out.join('->');
}

